package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var str string
	fmt.Fscan(in, &str)
	a, _ := strconv.Atoi(str)
	aMod, _ := strconv.Atoi(strings.ReplaceAll(str, "0", ""))

	fmt.Fscan(in, &str)
	b, _ := strconv.Atoi(str)
	bMod, _ := strconv.Atoi(strings.ReplaceAll(str, "0", ""))

	c := a + b
	cMod, _ := strconv.Atoi(strings.ReplaceAll(strconv.Itoa(c), "0", ""))

	if aMod+bMod == cMod {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func removeZeros(s string) int {
	value, _ := strconv.Atoi(strings.ReplaceAll(s, "0", ""))
	return value
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var strA, strB string
	fmt.Fscan(in, &strA, &strB)

	a, _ := strconv.Atoi(strA)
	b, _ := strconv.Atoi(strB)

	aMod := removeZeros(strA)
	bMod := removeZeros(strB)
	cMod := removeZeros(strconv.Itoa(a + b))

	if aMod+bMod == cMod {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

