package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func parseInt(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		panic(err)
	}
	return n
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	scanner.Scan()
	str := scanner.Text()
	a := parseInt(str)
	aMod := parseInt(strings.ReplaceAll(str, "0", ""))

	scanner.Scan()
	str = scanner.Text()
	b := parseInt(str)
	bMod := parseInt(strings.ReplaceAll(str, "0", ""))

	c := a + b
	cMod := parseInt(strings.ReplaceAll(strconv.Itoa(c), "0", ""))

	if aMod+bMod == cMod {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

